import React, { useState, useEffect } from 'react';

function DocumentManager() {
  const [documents, setDocuments] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [uploadForm, setUploadForm] = useState({
    document_name: '',
    notes: '',
    file: null
  });

  useEffect(() => {
    fetchDocuments();
  }, [searchTerm]);

  const fetchDocuments = async () => {
    const url = searchTerm 
      ? `/api/documents?search=${searchTerm}`
      : '/api/documents';

    const response = await fetch(url, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await response.json();
    setDocuments(data.data.data);
  };

  const handleUpload = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('document_name', uploadForm.document_name);
    formData.append('notes', uploadForm.notes);
    formData.append('file', uploadForm.file);

    await fetch('/api/documents', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}` },
      body: formData
    });

    setUploadForm({ document_name: '', notes: '', file: null });
    fetchDocuments();
  };

  const handleDelete = async (id) => {
    if (confirm('Delete this document?')) {
      await fetch(`/api/documents/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      fetchDocuments();
    }
  };

  return (
    <div>
      <h1>My Documents</h1>

      <form onSubmit={handleUpload}>
        <input
          type="text"
          placeholder="Document Name"
          value={uploadForm.document_name}
          onChange={(e) => setUploadForm({...uploadForm, document_name: e.target.value})}
          required
        />
        <textarea
          placeholder="Notes (optional)"
          value={uploadForm.notes}
          onChange={(e) => setUploadForm({...uploadForm, notes: e.target.value})}
        />
        <input
          type="file"
          onChange={(e) => setUploadForm({...uploadForm, file: e.target.files[0]})}
          required
        />
        <button type="submit">Upload</button>
      </form>

      <input
        type="text"
        placeholder="Search documents..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />

      <div>
        {documents.map(doc => (
          <div key={doc.id}>
            <h3>{doc.document_name}</h3>
            <p>{doc.notes}</p>
            <p>Size: {doc.file_size_formatted}</p>
            <a href={doc.file_url} target="_blank">View</a>
            <a href={`/api/documents/${doc.id}/download`}>Download</a>
            <button onClick={() => handleDelete(doc.id)}>Delete</button>
          </div>
        ))}
      </div>
    </div>
  );
}
